def select_endpoint(primary, fallback) -> str:
    """Return the first usable endpoint."""
    if primary is not None:
        return primary
    else:
        if fallback is not None:
            return fallback
        else:
            raise ValueError("No usable endpoint found")

def select_endpoint(primary, fallback) -> str:
    """Return the first usable endpoint."""
    if primary is not None:
        return primary
    else:
        if fallback is not None:
            return fallback
        else:
            raise ValueError("No usable endpoint found")
